function Suggestions({ term }: { term: string }) {
  const [results, setResults] = useState<Suggestion[]>([]);
  useEffect(() => {
    if (term.length < 2) {
      return;
    }
    void searchProducts(term).then(setResults);
  }, [term]);
  return <SuggestionList items={results} />;
}

